    return runs;
}

// ----------------------------------------------------------------- image ---

struct ImgNode {
    int kind;              // 0 internal, 1 leaf
    int mode;
    int cached;
    int lo;
    int span;
    int count;             // children for internal, span for leaf
    u32 allocated;
    u32 offset;
    Key base;
    std::vector<u32> children;   // byte offsets, internal only
    std::vector<Key> keys;       // absolute keys
};

struct Img {
    std::vector<u8> bytes;
    u32 runs = 0, nodes = 0, hop_offset = 0, total = 0;
    std::vector<ImgNode> records;         // record order
    std::map<u32, size_t> index;          // byte offset -> record slot
    std::vector<int> hops;                // -1 for null

    int lookup(Key address, std::vector<u32>& path) const {
        size_t slot = index.at(64);
        int run = 0;
        for (;;) {
            const ImgNode& node = records[slot];
            path.push_back(node.offset);
            const std::vector<Key>& keys = node.keys;
            size_t at = (size_t)(std::upper_bound(keys.begin(), keys.end(), address) - keys.begin());
            if (node.kind == 1) {
                if (at == 0) throw std::runtime_error("leaf predecessor");
                run = node.lo + (int)at - 1;
                return run;
            }
            if (at > node.children.size()) at = node.children.size();
            slot = index.at(node.children[at]);
        }
    }
};

inline u32 align64(u32 value) { return (value + 63u) & ~63u; }

// Layout row as supplied by PACK.
struct Layout {
    int lo, span, mode, cached;
    std::vector<int> children;
};

inline u32 node_used(const ImgNode& n) {
    if (n.kind == 1) return 32u + (u32)n.span * (u32)KEY_WIDTH[n.mode];
    u32 b = (u32)n.children.size();
    return 32u + 4u * b + (b - 1u) * (u32)KEY_WIDTH[n.mode];
}

inline Img decode_image(const std::vector<u8>& raw) {
    Img img;
    if (raw.size() < 128 || raw.size() % 64) throw std::runtime_error("image size");
    if (std::memcmp(raw.data(), "FIDX", 4) != 0 || raw[4] != 2)
        throw std::runtime_error("image magic");
    img.bytes = raw;
    img.runs = get_u32(raw.data() + 8);
    img.nodes = get_u32(raw.data() + 12);
    img.hop_offset = get_u32(raw.data() + 16);
    img.total = get_u32(raw.data() + 20);
    if (img.total != raw.size()) throw std::runtime_error("image total");
    if (img.runs < 1 || img.nodes < 1) throw std::runtime_error("image counts");
    for (u32 n = 0; n < img.nodes; ++n) {
        u32 off = (u32)(64 + (size_t)n * 0);   // replaced below by walk
        (void)off;
        break;
    }
    u32 offset = 64;
    for (u32 n = 0; n < img.nodes; ++n) {
        if (offset + 32 > img.hop_offset) throw std::runtime_error("truncated node");
        ImgNode node;
        const u8* p = raw.data() + offset;
        node.kind = p[0];
        node.mode = p[1];
        node.cached = p[2];
        if (p[3] != 0) throw std::runtime_error("node reserved");
        node.lo = get_u16(p + 4);
        node.span = get_u16(p + 6);
        node.count = get_u16(p + 8);
        node.allocated = get_u32(p + 12);
        node.offset = offset;
        node.base = get_key(p + 16, 0);
        if (node.mode < 0 || node.mode > 2) throw std::runtime_error("node mode");
        size_t cursor = (size_t)offset + 32;
        if (node.kind == 0) {
            int b = node.count;
            if (b < 2 || b > 9) throw std::runtime_error("child count");
            node.children.resize(b);
            for (int c = 0; c < b; ++c) {
                node.children[c] = get_u32(raw.data() + cursor);
                cursor += 4;
            }
            for (int c = 0; c < b - 1; ++c) {
                node.keys.push_back(node.base + get_key(raw.data() + cursor, node.mode));
                cursor += KEY_WIDTH[node.mode];
            }
        } else if (node.kind == 1) {
            int s = node.span;
            if (s < 1 || s > 8 || node.count != s) throw std::runtime_error("leaf span");
            for (int t = 0; t < s; ++t) {
                node.keys.push_back(node.base + get_key(raw.data() + cursor, node.mode));
                cursor += KEY_WIDTH[node.mode];
            }
        } else {
            throw std::runtime_error("node kind");
        }
        img.index[offset] = img.records.size();
        img.records.push_back(std::move(node));
        offset += img.records.back().allocated;
    }
    if (offset != img.hop_offset) throw std::runtime_error("node walk");
    img.hops.resize(img.runs);
    for (u32 r = 0; r < img.runs; ++r) {
        u32 value = get_u32(raw.data() + (size_t)img.hop_offset + 4 * (size_t)r);
        img.hops[r] = (value == 0xffffffffu) ? -1 : (int)value;
    }
    return img;
}

inline std::string image_hex(const std::vector<u8>& raw) {
    static const char* digits = "0123456789abcdef";
    std::string out;
    out.resize(raw.size() * 2);
    for (size_t i = 0; i < raw.size(); ++i) {
        out[2 * i] = digits[(raw[i] >> 4) & 15];
        out[2 * i + 1] = digits[raw[i] & 15];
    }
    return out;
}

// Build the unique exact FIDX version 2 image for one supplied layout.
inline std::vector<u8> pack_bytes(const std::vector<Key>& starts,
                                  const std::vector<int>& hops,
                                  const std::vector<Layout>& layout) {
    size_t R = starts.size(), N = layout.size();
    if (R < 1 || R > 64) throw std::runtime_error("run count");
    if (N < 1 || N > 2 * R - 1) throw std::runtime_error("node count");
    std::vector<u32> allocated(N), offset(N);
    u32 cursor = 64;
    for (size_t n = 0; n < N; ++n) {
        const Layout& node = layout[n];
        u32 used;
        if (node.children.empty()) {
            used = 32u + (u32)node.span * (u32)KEY_WIDTH[node.mode];
        } else {
            u32 b = (u32)node.children.size();
            used = 32u + 4u * b + (b - 1u) * (u32)KEY_WIDTH[node.mode];
        }
        allocated[n] = align64(used);
        offset[n] = cursor;
        cursor += allocated[n];
    }
    u32 hop_offset = cursor;
    u32 total = hop_offset + (u32)(((R * 4 + 63) / 64) * 64);
    std::vector<u8> raw(total, 0);
    std::memcpy(raw.data(), "FIDX", 4);
    raw[4] = 2;
    put_u32(raw, 8, (u32)R);
    put_u32(raw, 12, (u32)N);
    put_u32(raw, 16, hop_offset);
    put_u32(raw, 20, total);
    for (size_t n = 0; n < N; ++n) {
        const Layout& node = layout[n];
        size_t at = offset[n];
        int internal = node.children.empty() ? 0 : 1;
        raw[at + 0] = (u8)(internal ? 0 : 1);
        raw[at + 1] = (u8)node.mode;
        raw[at + 2] = (u8)node.cached;
        raw[at + 3] = 0;
        put_u16(raw, at + 4, (u16)node.lo);
        put_u16(raw, at + 6, (u16)node.span);
        put_u16(raw, at + 8, (u16)(internal ? node.children.size() : node.span));
        put_u16(raw, at + 10, 0);
        put_u32(raw, at + 12, allocated[n]);
        put_key(raw, at + 16, starts[node.lo], 0);
        size_t pay = at + 32;
        Key base = starts[node.lo];
        if (internal) {
            for (size_t c = 0; c < node.children.size(); ++c) {
                put_u32(raw, pay, offset[node.children[c]]);
                pay += 4;
            }
            for (size_t c = 1; c < node.children.size(); ++c) {
                const Layout& child = layout[node.children[c]];
                put_key(raw, pay, starts[child.lo] - base, node.mode);
                pay += KEY_WIDTH[node.mode];
            }
        } else {
            for (int t = 0; t < node.span; ++t) {
                put_key(raw, pay, starts[node.lo + t] - base, node.mode);
                pay += KEY_WIDTH[node.mode];
            }
        }
    }
    for (size_t r = 0; r < R; ++r) {
        u32 value = (hops[r] < 0) ? 0xffffffffu : (u32)hops[r];
        put_u32(raw, hop_offset + 4 * r, value);
    }
    return raw;
}

struct Answer {
    int hop;
    int run;
    std::vector<u32> path;
};

inline std::vector<Answer> search(const Img& img, const std::vector<Key>& addresses) {
    std::vector<Answer> out;
    out.reserve(addresses.size());
    for (Key address : addresses) {
        Answer answer;
        answer.path.clear();
        answer.run = img.lookup(address, answer.path);
        answer.hop = img.hops[answer.run];
        out.push_back(std::move(answer));
    }
    return out;
}

inline std::vector<Answer> trace_image(const std::vector<u8>& raw,
                                       const std::vector<Key>& addresses) {
    Img img = decode_image(raw);
    return search(img, addresses);
}
