"""Independent reference implementations for stress testing (not submitted)."""
import itertools, random
from bisect import bisect_right

U = 1 << 128
WIDTH = (16, 8, 4)
LANES = (4, 8, 16)


def ref_runs(routes):
    """Naive boundary-sampling LPM compilation. routes: dict (start,len)->hop."""
    pts = {0, U}
    for (s, l) in routes:
        pts.add(s)
        pts.add(s + (1 << (128 - l)) if l else U)
    pts = sorted(pts)
    starts, hops = [], []
    for a, b in zip(pts, pts[1:]):
        if a == b:
            continue
        best = None
        for (s, l), h in routes.items():
            e = s + (1 << (128 - l)) if l else U
            if s <= a < e and (best is None or l > best[0]):
                best = (l, h)
        hop = None if best is None else best[1]
        if hops and hops[-1] == hop:
            continue
        starts.append(a)
        hops.append(hop)
    if not starts:
        return [0], [None]
    return starts, hops


def ref_changes(old, new):
    (sa, ha), (sb, hb) = old, new
    pts = sorted(set(sa) | set(sb) | {U})
    rows = []
    for a, b in zip(pts, pts[1:]):
        x = ha[bisect_right(sa, a) - 1]
        y = hb[bisect_right(sb, a) - 1]
        if x != y:
            if rows and rows[-1][1] == a and rows[-1][2] == x and rows[-1][3] == y:
