inline const int KEY_WIDTH[3] = {16, 8, 4};

inline std::string hexkey(Key x) {
    static const char* digits = "0123456789abcdef";
    std::string s(32, '0');
    for (int i = 31; i >= 0; --i) {
        s[i] = digits[(unsigned)(x & 15)];
        x >>= 4;
    }
    return s;
}

inline int hexdigit(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

inline Key key(const std::string& s) {
    if (s.empty() || s.size() > 32) throw std::runtime_error("key width");
    Key value = 0;
    for (char c : s) {
        int d = hexdigit(c);
        if (d < 0) throw std::runtime_error("key digit");
        value = (value << 4) | (Key)d;
    }
    return value;
}

inline std::vector<u8> unhex(const std::string& s) {
    if (s.size() % 2) throw std::runtime_error("hex length");
    std::vector<u8> out(s.size() / 2);
    for (size_t i = 0; i < out.size(); ++i) {
        int hi = hexdigit(s[2 * i]), lo = hexdigit(s[2 * i + 1]);
        if (hi < 0 || lo < 0) throw std::runtime_error("hex digit");
        out[i] = (u8)((hi << 4) | lo);
    }
    return out;
}

